package com.profa.school;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/v1/schools")public class SchoolController{final SchoolRepository repo;public SchoolController(SchoolRepository r){repo=r;}@GetMapping("/me")@PreAuthorize("hasRole('SCHOOL')")public SchoolProfile me(Authentication a){return repo.findByUserId(UUID.fromString(a.getName())).orElseThrow();}@PutMapping("/me")@PreAuthorize("hasRole('SCHOOL')")public SchoolProfile update(Authentication a,@RequestBody SchoolProfile in){SchoolProfile p=repo.findByUserId(UUID.fromString(a.getName())).orElseThrow();p.setName(in.getName());p.setCity(in.getCity());p.setDistrict(in.getDistrict());p.setAddress(in.getAddress());p.setDescription(in.getDescription());p.setLogoUrl(in.getLogoUrl());p.setWebsite(in.getWebsite());p.setPhone(in.getPhone());p.setEmployeeCount(in.getEmployeeCount());return repo.save(p);}}
